import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { relative, resolve, sep } from "node:path";
import type { Plugin, ResolvedConfig } from "vite";

/** Static output a change to which must invalidate the app shell cache. */
const PRECACHE_EXTENSIONS = new Set([
  ".html",
  ".webmanifest",
  ".svg",
  ".png",
  ".jpg",
  ".jpeg",
  ".webp",
  ".ico",
  ".json",
  ".js",
  ".css",
  ".woff",
  ".woff2"
]);

/** Generated by this plugin, not part of the shell; `_headers` is a host directive, maps are debug data. */
function isExcluded(relativePath: string): boolean {
  const name = relativePath.split("/").pop() || relativePath;
  return name === "sw.js" || name === "_headers" || relativePath.endsWith(".map");
}

function hasCachableExtension(relativePath: string): boolean {
  const dot = relativePath.lastIndexOf(".");
  if (dot < 0) return false;
  return PRECACHE_EXTENSIONS.has(relativePath.slice(dot).toLowerCase());
}

function collectFiles(directory: string, root: string, files: string[] = []): string[] {
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const absolute = resolve(directory, entry.name);
    if (entry.isDirectory()) {
      collectFiles(absolute, root, files);
      continue;
    }
    if (!entry.isFile()) continue;
    const relativePath = relative(root, absolute).split(sep).join("/");
    if (isExcluded(relativePath) || !hasCachableExtension(relativePath)) continue;
    files.push(relativePath);
  }
  return files.sort();
}

function buildHash(outDir: string, files: string[]): string {
  const hash = createHash("sha256");
  for (const file of files) {
    hash.update(file);
    hash.update("\0");
    hash.update(readFileSync(resolve(outDir, file)));
    hash.update("\0");
  }
  return hash.digest("hex").slice(0, 12);
}

export function buildServiceWorker(buildId: string, files: string[]): string {
  return `/*
 * Jantt offline application shell, generated at build time.
 * Each installation owns a versioned cache under its registration scope.
 */
const PREFIX = "jantt-shell:" + self.registration.scope + ":";
const CACHE_NAME = PREFIX + ${JSON.stringify(buildId)};
const FILES = ${JSON.stringify(files)};
const shellUrl = new URL("index.html", self.registration.scope).href;
const shell = new Set(FILES.map(file => new URL(file, self.registration.scope).href));
const immutable = /\\/assets\\/.*-[A-Za-z0-9_-]{6,}\\.(js|css|woff2?)$/i;

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const existed = await caches.has(CACHE_NAME);
    const cache = await caches.open(CACHE_NAME);
    // addAll is transactional. Keep the working release active if a new chunk fails to download.
    try {
      await cache.addAll(Array.from(shell, url => new Request(url, { cache: "reload" })));
    } catch (error) {
      if (!existed) await caches.delete(CACHE_NAME);
      throw error;
    }
    if (!self.registration.active) await self.skipWaiting();
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const old = (await caches.keys()).filter(name => name.startsWith(PREFIX) && name !== CACHE_NAME);
    // A second open tab may still request a lazy chunk from the preceding release.
    await Promise.all(old.slice(0, -1).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener("message", event => {
  if (event.data?.type === "SKIP_WAITING") event.waitUntil(self.skipWaiting());
});

self.addEventListener("fetch", event => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  url.search = "";
  url.hash = "";
  // Query parameters select a room, view or shortcut. All launch the installed version's index.
  const key = url.href === self.registration.scope && request.mode === "navigate" ? shellUrl : url.href;
  if (!shell.has(key) && !immutable.test(url.pathname)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const hit = await cache.match(key);
    if (hit) return hit;
    if (immutable.test(url.pathname)) {
      const older = (await caches.keys()).filter(name => name.startsWith(PREFIX) && name !== CACHE_NAME);
      for (const name of older) {
        const previous = await caches.open(name);
        const asset = await previous.match(key);
        if (asset) return asset;
      }
    }
    return fetch(request);
  })());
});
`;
}

/**
 * Zero-dependency Vite plugin that emits a deterministic offline app-shell service worker after
 * every production build. The cache name is derived from the emitted shell files, so a deploy
 * that changes any asset installs a fresh cache and never serves stale HTML.
 */
export function janttPwaPlugin(): Plugin {
  let resolvedConfig: ResolvedConfig | null = null;

  return {
    name: "jantt-pwa",
    apply: "build",
    configResolved(config) {
      resolvedConfig = config;
    },
    async closeBundle() {
      if (!resolvedConfig) return;
      const outDir = resolve(resolvedConfig.root, resolvedConfig.build.outDir);
      if (!existsSync(outDir) || !statSync(outDir).isDirectory()) return;

      const files = collectFiles(outDir, outDir);
      if (files.length === 0) return;

      const buildId = buildHash(outDir, files);
      writeFileSync(resolve(outDir, "sw.js"), buildServiceWorker(buildId, files), "utf8");
      resolvedConfig.logger.info(
        `jantt-pwa: ${buildId} with ${files.length} shell files`,
        { timestamp: true }
      );
    }
  };
}
